__doc__ = """Symbolic helper routines for analysing array index expressions."""

from .expression import Constant, Variable, Mul, Add


class InconclusiveTestResultException(Exception):
    """Raised when an index-expression test cannot reach a conclusion."""

    def __init__(self, test, text, *args, **kwargs):
        super().__init__(
            f"the test {test.identifier} was inconclusive" + f": {text}."
            if text
            else "",
            *args,
            **kwargs,
        )


class IndexExpressionTest:
    """Base helper for symbolic index-expression property checks."""

    def __init__(self, identifier, renderer=None):
        self._identifier = identifier
        self._renderer = renderer

    @property
    def identifier(self):
        return self._identifier

    def apply_test(self, input_array):
        if not input_array:
            raise InconclusiveTestResultException(self, "empty input")
        return self._apply_test(input_array)

    def _apply_test(self, input_array):
        raise NotImplementedError("must be implemented in subclass")


class IsConstantIET(IndexExpressionTest):
    """Test whether an expression is constant with respect to the index."""

    def __init__(self, name=None, **kwargs):
        super().__init__(name or "is_constant", **kwargs)

    def _apply_test(self, input_array):
        assert len(input_array) > 0
        first = input_array[0]
        if len(input_array) > 1:
            for value in input_array:
                if value != first:
                    return None
        return Constant(first)


class IsCountIET(IndexExpressionTest):
    """Test whether an expression matches a simple counting pattern."""

    def __init__(self, name=None, **kwargs):
        super().__init__(name or "is_count", **kwargs)

    def _apply_test(self, input_array):
        assert len(input_array) > 0
        for num, value in enumerate(input_array):
            if value != num:
                return None
        return Variable("alpha")


class IsOffsetCountIET(IsCountIET):
    """Test whether an expression is a count plus a constant offset."""

    def __init__(self, name=None, **kwargs):
        super().__init__(name or "is_offset_count", **kwargs)

    def _apply_test(self, input_array):
        assert len(input_array) > 0
        offset = input_array[0]
        inner = super()._apply_test([val - offset for val in input_array])
        if inner:
            return Add(inner, Constant(offset))
        return None


class IsScaledCountIET(IsCountIET):
    """Test whether an expression is a scaled counting pattern."""

    def __init__(self, name=None, **kwargs):
        super().__init__(name or "is_offset_count", **kwargs)

    def _apply_test(self, input_array):
        assert len(input_array) > 1
        rise = input_array[1] - input_array[0]
        if rise == 0:
            return None
        inner = super()._apply_test([val / rise for val in input_array])
        if inner:
            return Mul(inner, Constant(rise))
        return None


class IsLinearIET(IsOffsetCountIET, IsScaledCountIET):
    """Test whether an expression is linear in the tracked index."""

    # MRO is important here!
    def __init__(self, name=None, **kwargs):
        super().__init__(name or "is_linear", **kwargs)


if __name__ == "__main__":
    test_arrays = {
        "zero": [0, 0, 0, 0, 0, 0, 0, 0],
        "constant": [7, 7, 7, 7, 7, 7, 7, 7],
        "count": [0, 1, 2, 3, 4, 5, 6, 7],
        "scaled": [0, 3, 6, 9, 12, 15, 18, 21],
        "offsetted": [2, 3, 4, 5, 6, 7, 8, 9],
        "linear": [6, 8, 10, 12, 14, 16, 18, 20],
    }

    isconstant = IsConstantIET()
    iscount = IsCountIET()
    isoffsetcount = IsOffsetCountIET()
    isscaledcount = IsScaledCountIET()
    islinear = IsLinearIET()

    for aname, array in test_arrays.items():
        print(f"testing '{aname}' = {array}")
        print(f"  isconstant    : {isconstant.apply_test(array)}")
        print(f"  iscount       : {iscount.apply_test(array)}")
        print(f"  isoffsetcount : {isoffsetcount.apply_test(array)}")
        print(f"  isscaledcount : {isscaledcount.apply_test(array)}")
        print(f"  islinear      : {islinear.apply_test(array)}")

        print()
